package com.example.jalalidaily;
import android.app.*;import android.appwidget.*;import android.content.*;import android.graphics.Color;import android.text.*;import android.text.style.*;import android.view.View;import android.widget.*;import java.time.*;import org.json.*;
public final class Widgets {
 static final String ACTION_TOGGLE_TASK="com.example.jalalidaily.ACTION_TOGGLE_TASK";
 static final int[] THEMES={R.drawable.widget_day_0,R.drawable.widget_day_1,R.drawable.widget_day_2,R.drawable.widget_day_3,R.drawable.widget_day_4,R.drawable.widget_day_5,R.drawable.widget_day_6};
 static final int[] ROWS={R.id.task_0,R.id.task_1,R.id.task_2,R.id.task_3,R.id.task_4,R.id.task_5};
 static String fa(String s){return s.replace('0','۰').replace('1','۱').replace('2','۲').replace('3','۳').replace('4','۴').replace('5','۵').replace('6','۶').replace('7','۷').replace('8','۸').replace('9','۹');}
 static LocalDate iranToday(){return LocalDate.now(ZoneId.of("Asia/Tehran"));}
 static int weekday(LocalDate d){return (d.getDayOfWeek().getValue()+1)%7;}
 static String date(LocalDate d){int[] a=Jalali.fromGregorian(d);String[] days={"شنبه","یکشنبه","دوشنبه","سه‌شنبه","چهارشنبه","پنجشنبه","جمعه"};return fa(days[weekday(d)]+"، "+Jalali.label(a));}
 static void update(Context c,Class<?> cls,int layout,boolean notes){AppWidgetManager manager=AppWidgetManager.getInstance(c);int[] ids=manager.getAppWidgetIds(new ComponentName(c,cls));LocalDate today=iranToday();String dateKey=DayBundles.keyFromDate(today);if(notes)DayBundles.ensureIds(c,dateKey);
 for(int id:ids){try{RemoteViews v=new RemoteViews(c.getPackageName(),layout);v.setTextViewText(R.id.date_text,date(today));v.setImageViewResource(R.id.widget_header_image,THEMES[weekday(today)]);
 PendingIntent open=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);v.setOnClickPendingIntent(R.id.widget_root,open);v.setOnClickPendingIntent(R.id.widget_header,open);v.setOnClickPendingIntent(R.id.date_text,open);if(notes)v.setOnClickPendingIntent(R.id.notes_empty,open);
 if(notes){JSONArray tasks=DayBundles.get(c,dateKey);v.setViewVisibility(R.id.notes_empty,tasks.length()==0?View.VISIBLE:View.GONE);for(int i=0;i<ROWS.length;i++){int view=ROWS[i];JSONObject o=tasks.optJSONObject(i);if(o==null){v.setViewVisibility(view,View.GONE);continue;}v.setViewVisibility(view,View.VISIBLE);boolean done=o.optBoolean("done");String label=fa((done?"☑  ":"○  ")+o.optString("emoji","📝")+"  "+o.optString("text"));SpannableString span=new SpannableString(label);if(done){span.setSpan(new StrikethroughSpan(),0,label.length(),Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);span.setSpan(new ForegroundColorSpan(Color.GRAY),0,label.length(),Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);}v.setTextViewText(view,span);
 Intent toggle=new Intent(c,NotesWidget.class).setAction(ACTION_TOGGLE_TASK).putExtra("taskId",o.optString("id"));PendingIntent click=PendingIntent.getBroadcast(c,1000+i,new Intent(toggle).setData(android.net.Uri.parse("jalali://toggle/"+o.optString("id"))),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);v.setOnClickPendingIntent(view,click);}}
 manager.updateAppWidget(id,v);}catch(Exception e){android.util.Log.e("JalaliWidget","Update failed",e);}}}
 static void refresh(Context c){RolloverReceiver.schedule(c);try{DayBundles.rolloverUnfinishedTasks(c);}catch(Exception e){android.util.Log.e("JalaliWidget","Rollover failed",e);}try{update(c,DateWidget.class,R.layout.widget_date,false);}catch(Exception e){android.util.Log.e("JalaliWidget","Date failed",e);}try{update(c,NotesWidget.class,R.layout.widget_notes,true);}catch(Exception e){android.util.Log.e("JalaliWidget","Notes failed",e);}}
}
